export type SignalType = 'time' | 'dimension' | 'measure';
export type SemanticRole = 'time' | 'dimension' | 'measure' | 'status' | 'identifier';
export type SemanticCoverageSupport = 'supported' | 'partial' | 'advertised_only';

export interface SemanticSignalDefinition {
  canonicalId: string;
  domain: string;
  label: string;
  type: SignalType;
  domains: string[];
  semanticFamily: string;
  role: SemanticRole;
  coverageStatus: SemanticCoverageSupport;
  aliases: string[];
  exactHeaderAliases?: string[];
  headerAliases: string[];
  valueAliases: string[];
  valuePatterns: RegExp[];
  compatibleTypes: string[];
}

const STRING_TYPES = ['string', 'varchar', 'text'];
const NUMBER_TYPES = ['number', 'integer', 'float', 'double', 'decimal', 'currency'];

function signal(definition: Omit<SemanticSignalDefinition, 'domains' | 'coverageStatus' | 'exactHeaderAliases' | 'headerAliases' | 'valueAliases' | 'valuePatterns' | 'compatibleTypes'> & {
  domains?: string[];
  coverageStatus?: SemanticCoverageSupport;
  exactHeaderAliases?: string[];
  headerAliases?: string[];
  valueAliases?: string[];
  valuePatterns?: RegExp[];
  compatibleTypes?: string[];
}): SemanticSignalDefinition {
  return {
    ...definition,
    domains: definition.domains ?? [definition.domain],
    coverageStatus: definition.coverageStatus ?? 'supported',
    exactHeaderAliases: definition.exactHeaderAliases ?? [],
    headerAliases: definition.headerAliases ?? definition.aliases,
    valueAliases: definition.valueAliases ?? [],
    valuePatterns: definition.valuePatterns ?? [],
    compatibleTypes: definition.compatibleTypes ?? (definition.type === 'measure' ? NUMBER_TYPES : definition.type === 'time' ? ['date', 'datetime', 'timestamp', ...STRING_TYPES] : STRING_TYPES)
  };
}

